def replace_paragraph_text(paragraph, new_text):
    if not paragraph.runs:
        paragraph.add_run(new_text)
        return
    paragraph.runs[0].text = new_text
    for run in paragraph.runs[1:]:
        run.text = ""


def main():
    document = Document(SOURCE)
    replaced = 0
    for paragraph in document.paragraphs:
        old = paragraph.text.strip()
        if old in REPLACEMENTS:
            replace_paragraph_text(paragraph, REPLACEMENTS[old])
            replaced += 1

    if replaced != len(REPLACEMENTS):
        raise RuntimeError(f"Expected {len(REPLACEMENTS)} text replacements but completed {replaced}.")

    document.save(OUTPUT)
    print(f"Created {OUTPUT} with {replaced} clearer, natural-language revisions.")


if __name__ == "__main__":
    main()
